+class ContactForm {
+    constructor() {
+        this.form = document.getElementById('contactForm');
+        this.successMessage = document.getElementById('successMessage');
+        this.submitButton = this.form.querySelector('.submit-button');
+        
+        this.init();
+    }
+
+    init() {
+        this.form.addEventListener('submit', (e) => this.handleSubmit(e));
+        this.setupFieldValidation();
+    }
+
+    setupFieldValidation() {
+        const fullNameInput = document.getElementById('fullName');
+        const emailInput = document.getElementById('email');
+        const phoneInput = document.getElementById('phone');
+
+        fullNameInput.addEventListener('blur', () => this.validateField(fullNameInput));
+        emailInput.addEventListener('blur', () => this.validateField(emailInput));
+        phoneInput.addEventListener('blur', () => this.validateField(phoneInput));
+    }
+
+    validateField(field) {
+        if (field.name === 'email') {
+            this.validateEmail(field);
+        } else if (field.name === 'phone' && field.value.trim() !== '') {
+            this.validatePhone(field);
+        }
+    }
+
+    validateEmail(field) {
+        const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
+        if (field.value.trim() !== '' && !emailRegex.test(field.value)) {
+            field.setAttribute('aria-invalid', 'true');
+            return false;
+        }
+        field.removeAttribute('aria-invalid');
+        return true;
+    }
+
+    validatePhone(field) {
+        const phoneRegex = /^[\+]?[(]?[0-9]{3}[)]?[-\s\.]?[0-9]{3}[-\s\.]?[0-9]{4,6}$/;
+        if (field.value.trim() !== '' && !phoneRegex.test(field.value)) {
+            field.setAttribute('aria-invalid', 'true');
+            return false;
+        }
+        field.removeAttribute('aria-invalid');
+        return true;
+    }
+
+    isFormValid() {
+        const fullNameInput = document.getElementById('fullName');
+        const emailInput = document.getElementById('email');
+        const phoneInput = document.getElementById('phone');
+
+        const isFullNameValid = fullNameInput.value.trim() !== '';
+        const isEmailValid = this.validateEmail(emailInput) && emailInput.value.trim() !== '';
+        const isPhoneValid = phoneInput.value.trim() === '' || this.validatePhone(phoneInput);
+
+        return isFullNameValid && isEmailValid && isPhoneValid;
+    }
+
+    handleSubmit(e) {
+        e.preventDefault();
+
+        if (!this.isFormValid()) {
+            return;
+        }
+
+        this.submitButton.disabled = true;
+        this.submitButton.textContent = 'Sending...';
+
+        setTimeout(() => {
+            this.form.style.display = 'none';
+            this.successMessage.style.display = 'block';
+
+            this.submitButton.disabled = false;
+            this.submitButton.textContent = 'Send Message';
+        }, 500);
+    }
+}
+
+document.addEventListener('DOMContentLoaded', () => {
+    new ContactForm();
+});
+
